"""Original asthma chapter: severe phenotypes, acute care and special situations."""
from create_asthma import rows,q,GI,EX,NI
from qbank_authoring import ref,finalize
CH=ref('CHEST: Biologic Management in Severe Asthma Guideline, 2026','https://www.chestnet.org/newsroom/press-releases/2026/01/chest-releases-guideline-on-biologic-management-in-severe-asthma')
AB=ref('ISHAM: Revised ABPA Clinical Practice Guideline, 2024','https://doi.org/10.1183/13993003.00061-2024')
q('When is asthma appropriately classified as severe rather than merely difficult to treat?', 'It remains uncontrolled despite optimized high-dose ICS-LABA with good adherence and management of contributory factors, or worsens when this is reduced',[
 ('Whenever symptoms persist before technique has been checked','This may be a modifiable difficult-to-treat problem.'),('Whenever a prescription contains a high dose, regardless of actual use','Prescribing does not establish delivered optimized therapy.'),('Whenever one eosinophil count is high in an untreated patient','A biomarker alone does not define severity.')],
 'Severe asthma is a retrospective classification after optimization', '**Confirm the diagnosis and remove modifiable causes first.**',['Comorbidities, exposures and access barriers can create apparent resistance.','The treatment required to maintain control also informs severity.'], '**Refer for phenotype-directed assessment.**',['Avoid repeated systemic steroid courses without reviewing the mechanism.','Use exacerbation history and patient priorities as well as symptoms.'],[['Difficult to treat','May have modifiable contributors'],['Severe','Persists despite optimized care'],['Next step','Specialist phenotype assessment']],[GI,CH])
q('Severe allergic asthma persists despite optimized inhaled treatment. Sensitization and IgE/weight dosing eligibility are appropriate. Which biologic class specifically targets IgE?', 'Omalizumab',[
 ('Mepolizumab','It targets IL-5.'),('Dupilumab','It targets IL-4 receptor alpha.'),('Tezepelumab','It targets TSLP.')],
 'Match the molecular target to a supported clinical phenotype', '**Anti-IgE reduces free IgE-mediated allergic signaling.**',['Eligibility uses sensitization and product-specific dosing criteria.','A high total IgE alone does not prove benefit or meet all criteria.'], '**Define response goals before starting.**',['Assess exacerbations, control, steroid exposure and tolerance.','Continue appropriate inhaled therapy and review response at a planned interval.'],[['Omalizumab','IgE'],['Mepolizumab','IL-5'],['Tezepelumab','TSLP']],[GI,CH])
q('A patient has severe eosinophilic asthma with recurrent exacerbations despite optimized inhaled therapy. Which treatment directly targets IL-5?', 'Mepolizumab',[
 ('Omalizumab','It targets IgE.'),('Dupilumab','It blocks IL-4 receptor alpha and related IL-4/IL-13 signaling.'),('Tezepelumab','It targets the upstream epithelial cytokine TSLP.')],
 'Eosinophilic biology supports an IL-5 pathway option', '**Anti-IL-5 or anti-IL-5-receptor therapies can reduce exacerbations in suitable eosinophilic disease.**',['Historical counts may help when current steroids suppress eosinophils.','Local eligibility and comorbid disease affect choice.'], '**Exclude other causes of marked eosinophilia.**',['Parasites, ABPA and systemic eosinophilic disease may change the plan.','Reassess clinical response rather than selecting indefinitely from one count.'],[['Target','IL-5'],['Phenotype','Eosinophilic severe asthma'],['Selection','History, biomarkers and comorbidity']],[GI,CH],'clinical_scenario')
q('Which asthma biologic blocks IL-4 receptor alpha, affecting both IL-4 and IL-13 signaling?', 'Dupilumab',[
 ('Omalizumab','It targets IgE.'),('Benralizumab','It targets IL-5 receptor alpha.'),('Tezepelumab','It targets TSLP.')],
 'A shared receptor component can interrupt two Type 2 pathways', '**Dupilumab is useful in selected Type 2 or steroid-dependent severe asthma.**',['Atopic dermatitis and nasal polyposis can influence selection.','Eosinophil behavior and adverse effects require monitoring.'], '**Choose based on the whole phenotype and evidence.**',['Do not substitute a biomarker label for optimized baseline care.','Review steroid reduction carefully after a response.'],[['Target','IL-4R alpha'],['Signals','IL-4 and IL-13'],['Context','Type 2 and selected OCS-dependent disease']],[GI,CH])
q('Which biologic targets the epithelial alarmin TSLP?', 'Tezepelumab',[
 ('Mepolizumab','It targets IL-5.'),('Omalizumab','It targets IgE.'),('Dupilumab','It targets IL-4R alpha.')],
 'An upstream target can affect several downstream inflammatory pathways', '**Tezepelumab is an option for selected severe asthma across a broader biomarker range.**',['Response magnitude can still relate to biomarkers.','Broad eligibility does not mean equal benefit in every phenotype or treatment goal.'], '**Define the clinical objective.**',['Exacerbation prevention and oral-steroid sparing have different evidence.','Use current guideline comparisons where options overlap.'],[['Target','TSLP'],['Position','Upstream epithelial pathway'],['Caution','Goal-specific evidence matters']],[GI,CH])
q('For severe asthma dependent on maintenance oral corticosteroids, what comparative suggestion is made by the 2026 CHEST biologic guideline?', 'Prefer anti-IL-5 therapy or dupilumab over tezepelumab for this particular steroid-dependent treatment goal',[
 ('All biologics have identical proven steroid-sparing evidence','The guideline distinguishes the evidence.'),('Tezepelumab is prohibited for every severe-asthma phenotype','The suggestion is specific to this clinical comparison.'),('Continue high-dose oral steroids indefinitely without evaluating alternatives','Steroid-sparing strategies can reduce harm.')],
 'Exacerbation benefit does not automatically equal maintenance-OCS-sparing benefit', '**The CHEST recommendation is a suggestion within a defined evidence context.**',['Biomarkers, comorbidities and product eligibility still matter.','Response should be reassessed rather than assumed.'], '**Taper systemic steroids with adrenal safety.**',['Do not stop long-term steroids abruptly after the first biologic dose.','Maintain an appropriate inhaled regimen.'],[['Clinical goal','Reduce maintenance OCS'],['Suggested options','Anti-IL-5 or dupilumab'],['Safety','Monitored steroid taper']],[CH,GI])
q('Asthma and eosinophilia are accompanied by mononeuritis multiplex, purpura and systemic illness. What should be considered before labeling isolated severe eosinophilic asthma?', 'Eosinophilic granulomatosis with polyangiitis',[
 ('Isolated atopy necessarily explains all systemic findings','Vasculitic neurological and skin disease are red flags.'),('A negative ANCA would exclude EGPA in every patient','Many cases are ANCA negative.'),('An inhaler change alone is sufficient regardless of organ findings','Systemic organ assessment is required.')],
 'Airway disease can be part of a multisystem eosinophilic disorder', '**Neuropathy, skin lesions and other organ injury broaden the differential.**',['Parasites, drugs and hypereosinophilic disorders are alternatives.','Steroid exposure can suppress the measured eosinophil count.'], '**Arrange prompt specialist evaluation.**',['Assess cardiac and other potentially serious involvement.','Select systemic therapy according to severity and the confirmed diagnosis.'],[['Airway','Asthma'],['Red flags','Neuropathy/purpura/systemic disease'],['Concern','EGPA or another systemic process']],[GI],'clinical_scenario')
q('Difficult asthma occurs with mucus plugs, suggestive bronchiectasis, Aspergillus sensitization and total IgE 720 IU/mL. What does the revised 2024 ISHAM framework imply?', 'ABPA should be evaluated; the total-IgE threshold is generally at least 500 rather than a mandatory 1,000',[
 ('ABPA is excluded solely because IgE is below 1,000','The revised threshold is lower.'),('Sensitization alone establishes ABPA without other evidence','Additional clinical, immunological or imaging criteria are required.'),('Every positive fungal culture proves invasive aspergillosis','Colonization, allergy and invasion are different processes.')],
 'Allergic fungal disease has a specific integrated definition', '**The framework requires fungal sensitization and elevated total IgE with additional supporting criteria.**',['Eosinophilia, fungal IgG and imaging can contribute.','High-attenuation mucus is a particularly important finding.'], '**Differentiate ABPA from fungal sensitization alone.**',['Treatment is syndrome specific rather than routine antibacterial therapy.','Review infection risk before systemic immunosuppression.'],[['Total IgE','Usually at least 500 IU/mL'],['Essential context','Fungal sensitization'],['Additional support','IgG/eosinophils/imaging']],[AB],'clinical_scenario')
q('A patient with an acute asthma attack becomes exhausted, drowsy and has barely audible breath sounds. What is the correct interpretation?', 'Life-threatening deterioration requiring urgent critical-care assessment',[
 ('Less wheeze proves the bronchospasm has resolved','Very low airflow can produce a silent chest.'),('Drowsiness is an expected harmless effect of improvement','It can signal respiratory failure.'),('Wait for the next outpatient spirometry','Acute resuscitation takes priority.')],
 'Sound intensity is not a linear marker of safety', '**A silent chest can reflect critically reduced air movement.**',['Altered consciousness and exhaustion are major danger signs.','Assess oxygenation and ventilation while providing treatment.'], '**Escalate immediately.**',['Prepare for airway support by an experienced team.','Do not delay on the basis of a falsely reassuring reduction in wheeze.'],[['Silent chest','Possible minimal airflow'],['Drowsiness/exhaustion','Danger signs'],['Response','Emergency critical-care escalation']],[GI],'clinical_scenario')
q('During a severe asthma attack, PaCO2 rises from low to normal despite ongoing marked distress. Why is this concerning?', 'Ventilatory compensation may be failing',[
 ('A normal PaCO2 always proves normal respiratory function','Severe attacks commonly cause hyperventilation and a low PaCO2.'),('It means no further reassessment is needed','The trend can precede hypercapnic failure.'),('Only oxygen saturation is relevant','Saturation does not fully assess ventilation.')],
 'A normal range can be physiologically inappropriate', '**Rising PaCO2 with persistent severe obstruction suggests fatigue or worsening ventilation.**',['Hypercapnia is a serious sign in this context.','Clinical state matters more than one isolated gas.'], '**Reassess urgently and escalate as needed.**',['Continue bronchodilator and anti-inflammatory care.','Plan airway support when the trajectory indicates failure.'],[['Earlier','Often low PaCO2'],['Concerning trend','Normalizing/rising with distress'],['Meaning','Possible ventilatory failure']],[GI],'clinical_scenario')
q('A severe adult asthma exacerbation reaches the emergency department. Which initial treatment bundle is appropriate?', 'Repeated inhaled rapid bronchodilation, ipratropium in severe disease, early systemic corticosteroid and titrated oxygen when needed',[
 ('An oral antibiotic alone while delaying bronchodilation','This does not treat the acute airflow emergency.'),('A sedative to reduce respiratory effort as routine first-line care','Sedation can worsen respiratory failure.'),('Wait for full formal spirometry before treatment','Acute treatment must not be delayed.')],
 'Act on airflow obstruction and inflammation in parallel', '**Inhaled SABA remains a key acute-care bronchodilator in appropriate protocols.**',['A pMDI with spacer can be effective when feasible.','Systemic steroids have a delayed effect and should be given early when indicated.'], '**Reassess response frequently.**',['Symptoms, work of breathing, airflow and oxygenation guide escalation.','Treat anaphylaxis with epinephrine when that is the cause.'],[['Bronchodilation','Rapid repeated inhaled treatment'],['Inflammation','Early systemic steroid'],['Support','Titrated oxygen and monitoring']],[GI],'clinical_scenario')
q('Under GINA 2026, what oxygen principle applies to most adults and adolescents with an asthma exacerbation who need supplemental oxygen?', 'Titrate toward saturation 92–95% rather than giving uncontrolled high-concentration oxygen',[
 ('Target 100% in every patient indefinitely','Unnecessary hyperoxia can be harmful.'),('Withhold oxygen despite important hypoxemia','Hypoxemia requires treatment.'),('Use the same flow rate without reassessing saturation','Delivery should be titrated to response.')],
 'Use a saturation target, not an unobserved fixed flow', '**The 2026 report updates the target to 92–95% for this age group.**',['Pulse oximetry and clinical assessment guide administration.','Special coexisting conditions can require individualization.'], '**Continue ventilation assessment.**',['A satisfactory saturation on oxygen does not exclude rising CO2.','Do not delay critical-care review for worsening consciousness or fatigue.'],[['Target','92–95% in this guidance'],['Method','Titrate to oximetry'],['Other dimension','Assess ventilation and clinical state']],[GI])
q('Severe asthma has not responded adequately to intensive initial bronchodilator and steroid treatment. Which adjunct can be considered?', 'A single monitored IV magnesium sulfate dose',[
 ('Routine IV magnesium for every mild cough','It is not indicated for all mild presentations.'),('Repeated sedatives to slow breathing','This can be dangerous.'),('Oral magnesium as an equivalent immediate rescue','The route and evidence differ.')],
 'An adjunct is selected for severity and poor initial response', '**IV magnesium can help selected severe exacerbations.**',['It is not a replacement for bronchodilators and corticosteroids.','Blood pressure, kidney function and toxicity risk require consideration.'], '**Use a validated emergency protocol.**',['Reassess rather than repeating indefinitely without indication.','Escalate respiratory support when the patient is failing.'],[['Indication','Selected severe poor response'],['Role','Adjunct'],['Safety','Monitored protocol and clinical review']],[GI])
q('Should antibiotics be routinely given for every asthma exacerbation?', 'No; use them when there is evidence supporting a bacterial infection or another specific indication',[
 ('Yes, because all attacks are bacterial','Viral and noninfectious triggers are common.'),('Purulent-looking sputum alone always proves bacterial pneumonia','Clinical assessment and other evidence are needed.'),('No infection can ever coexist with asthma','Pneumonia and other infections can require treatment.')],
 'Treat the cause that is actually present', '**Routine antibiotics do not address ordinary bronchospasm and inflammation.**',['Fever, focal findings and imaging can support a separate infection diagnosis.','Avoid unnecessary antibiotic harm and resistance.'], '**Do not let infection assessment delay acute asthma treatment.**',['Provide the indicated airflow and anti-inflammatory care.','Reassess an atypical or nonresolving course.'],[['Asthma attack','Not automatically bacterial'],['Antibiotic','Evidence-based indication'],['Core care','Bronchodilator and anti-inflammatory treatment']],[GI])
q('An intubated patient with severe asthma has dynamic hyperinflation. Which ventilator principle is important?', 'Allow adequate expiratory time and avoid excessive minute ventilation that worsens gas trapping',[
 ('Increase respiratory rate aggressively until PaCO2 is normal regardless of pressures','This can worsen auto-PEEP and hemodynamic compromise.'),('Ignore expiratory flow and plateau pressure','They help identify unsafe mechanics.'),('Use the same settings for every obstructive and restrictive lung disease','Mechanics differ.')],
 'The patient needs time to exhale through narrowed airways', '**Air trapping increases intrathoracic pressure and can impair venous return.**',['A lower respiratory rate and appropriate inspiratory flow can lengthen expiration.','Permissive hypercapnia may be accepted when safe.'], '**Use expert lung-protective monitoring.**',['Assess pressures, expiratory flow and hemodynamics.','Abrupt hypotension requires evaluation of hyperinflation and other causes such as pneumothorax.'],[['Problem','Dynamic hyperinflation'],['Strategy','Adequate expiration'],['Monitoring','Flow, pressures and circulation']],[GI],'clinical_scenario')
q('After an emergency asthma visit, which discharge element reduces future risk?', 'An ICS-containing regimen, inhaler teaching, a written action plan and early follow-up',[
 ('A new SABA prescription as the only long-term plan','Anti-inflammatory protection and review are needed.'),('No discussion of the trigger or previous controller use','The episode can expose preventable problems.'),('Stop all therapy once wheeze disappears','Risk persists after symptom improvement.')],
 'The attack is an opportunity to correct the prevention plan', '**Review the cause, treatment access and technique.**',['Teach when to increase treatment and seek urgent help.','Frequent attacks warrant specialist assessment.'], '**Confirm a practical regimen before leaving care.**',['Demonstrate the inhaler and check understanding.','Address smoking, occupational exposure and relevant comorbidities.'],[['Medicine','ICS-containing protection'],['Skills','Technique and action plan'],['Review','Early follow-up and trigger assessment']],[GI,NI])
q('A pregnant patient with well-controlled asthma worries about continuing ICS. What is the best general advice?', 'Continue appropriate asthma control and review the regimen rather than stopping necessary ICS',[
 ('Uncontrolled asthma is safer than all inhaled treatment','Poor control and hypoxemia can harm mother and fetus.'),('Pregnancy automatically cures asthma','The course varies.'),('All controller doses should be reduced regardless of prior attacks','Step-down requires caution and is not routine simply because of pregnancy.')],
 'Maintaining maternal respiratory stability protects both patients', '**Appropriate inhaled treatment has a favorable benefit-risk in pregnancy.**',['Monitor control and treat exacerbations promptly.','Review the exact products and comorbidities.'], '**Use a coordinated obstetric and respiratory plan.**',['Do not delay systemic steroid treatment when needed for a significant attack.','Avoid smoking and support vaccination and trigger prevention.'],[['Priority','Maintain control'],['ICS','Continue indicated therapy'],['Exacerbation','Treat promptly']],[GI],'clinical_scenario')
q('Exercise-related symptoms persist in a person with asthma. What is the best ongoing management principle?', 'Optimize anti-inflammatory control and use the prescribed pre-exercise or reliever strategy while encouraging safe activity',[
 ('Avoid all physical activity permanently','This is unnecessary for most people with well-managed asthma.'),('Frequent pre-exercise SABA alone replaces all inflammation treatment','This can leave underlying disease uncontrolled.'),('Every exercise symptom proves asthma rather than ILO or deconditioning','Alternative mechanisms should be considered.')],
 'Exercise limitation can be a control signal or a diagnostic clue', '**ICS-containing care reduces exercise-induced bronchoconstriction.**',['Warm-up and trigger planning can help.','The appropriate reliever option depends on the prescribed track.'], '**Confirm the cause of persistent symptoms.**',['Consider laryngeal obstruction, fitness and cardiac disease when appropriate.','Support activity with a practical action plan.'],[['Ongoing treatment','Control inflammation'],['Before activity','Prescribed individualized strategy'],['Persistent symptoms','Review diagnosis and control']],[GI,NI])

